 "content": "def transform(grid):
    # Infer a repeating output motif from the nonzero row sequence.
    rows = [row[:] for row in grid]
    n = len(rows)
    nonzero = [row for row in rows if any(row)]
    if not nonzero:
        return rows
    motif = None
    for p in range(1, len(nonzero) + 1):
        if all(nonzero[i] == nonzero[i % p] for i in range(len(nonzero))):
            motif = nonzero[:p]
            break
    if motif is None:
        motif = nonzero
    # Fill zero rows by continuing the vertical pattern established by colored rows.
    # Locate first colored row and repeat pattern through all rows.
    first = next(i for i, row in enumerate(rows) if any(row))
    period = len(motif)
    out = []
    for r in range(n):
        if r < first:
            out.append(motif[(r-first) % period][:])
        else:
            out.append(motif[(r-first) % period][:])
    return out
